package za.co.bacy.admin;
import android.graphics.Bitmap;import android.graphics.Canvas;import android.view.View;import java.io.File;import java.io.FileOutputStream;import org.json.JSONObject;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.Robolectric;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import org.robolectric.annotation.GraphicsMode;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w393dp-h851dp-xxhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class AdminScreenshotTest {
 @Test public void renderEmptyWorkspace()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().visible().get();a.overview=new JSONObject("{\"devices\":[],\"claims\":[],\"audit\":[],\"server_time\":1700000000}");a.render();View v=a.getWindow().getDecorView();v.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));v.layout(0,0,1179,2553);Bitmap bitmap=Bitmap.createBitmap(1179,2553,Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap));File out=new File("/workspace/loop-phone-manager/artifacts/bacy-admin-native.png");try(FileOutputStream s=new FileOutputStream(out)){bitmap.compress(Bitmap.CompressFormat.PNG,100,s);}org.junit.Assert.assertTrue(out.length()>20000);a.onDestroy();}

 @Test public void renderSignIn()throws Exception{MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().visible().get();a.login();View v=a.getWindow().getDecorView();v.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));v.layout(0,0,1179,2553);Bitmap bitmap=Bitmap.createBitmap(1179,2553,Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap));File out=new File("/workspace/loop-phone-manager/artifacts/bacy-admin-signin.png");try(FileOutputStream stream=new FileOutputStream(out)){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}org.junit.Assert.assertTrue(out.length()>20000);a.onDestroy();}
 @Test public void renderCustomerControls()throws Exception{
  MainActivity a=Robolectric.buildActivity(MainActivity.class).setup().visible().get();a.overview=new JSONObject("{\"devices\":[{\"id\":\"qa-only\",\"name\":\"Test account\",\"phone\":\"0600000000\",\"reference\":\"QA-ACCOUNT\",\"enforcement_status\":\"unrestricted\",\"last_seen\":1699999990}],\"claims\":[],\"audit\":[],\"server_time\":1700000000}");a.tab=1;a.render();View v=a.getWindow().getDecorView();v.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));v.layout(0,0,1179,2553);java.util.ArrayList<View> controls=new java.util.ArrayList<>();v.findViewsWithText(controls,"Unlock",View.FIND_VIEWS_WITH_TEXT);org.junit.Assert.assertEquals(1,controls.size());assertNavigationVisible(v);Bitmap bitmap=Bitmap.createBitmap(1179,2553,Bitmap.Config.ARGB_8888);v.draw(new Canvas(bitmap));try(FileOutputStream stream=new FileOutputStream("/workspace/loop-phone-manager/artifacts/loop-admin-controls-qa.png")){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}a.onDestroy();
 }
 private void assertNavigationVisible(View decor){for(String name:new String[]{"Overview","Clients","Payments","More"}){java.util.ArrayList<View> found=new java.util.ArrayList<>();decor.findViewsWithText(found,name,View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);found.removeIf(item->!name.contentEquals(item.getContentDescription())&&!(name+", current screen").contentEquals(item.getContentDescription()));org.junit.Assert.assertEquals(name,1,found.size());android.graphics.Rect bounds=new android.graphics.Rect();View item=found.get(0);org.junit.Assert.assertTrue(name,item.getGlobalVisibleRect(bounds));org.junit.Assert.assertEquals(name+" full width",item.getWidth(),bounds.width());}}
}